  const { fps: f } = useVideoConfig();
  const prog = spring({ frame, fps: f, delay, config: { damping: 200 } });
  return (
    <div style={{ position: "absolute", left: `${x}%`, top: `${y}%`, transform: `translate(-50%, -50%) scale(${prog})`, display: "flex", flexDirection: "column", alignItems: "center" }}>
