                  <div key={d.name} style={{ display: "flex", alignItems: "center", gap: 20 }}>
                    {/* Label — fixed width so bars align */}
                    <div style={{ width: 180, fontSize: 28, color: COLORS.muted, textAlign: "right", flexShrink: 0 }}>
                      {d.name}
