                preserving its aspect ratio — so circles always stay circular.
              */}
              <div style={{ width: "100%", display: "flex", justifyContent: "center" }}>
                <svg
                  width={SCATTER_W}
                  height={SCATTER_H}
                  viewBox={`0 0 ${SCATTER_W} ${SCATTER_H}`}
                  style={{ display: "block", maxWidth: "100%", height: "auto" }}
