                  {/* Axes */}
                  <line x1={SP_LEFT} y1={SP_BOTTOM} x2={SP_RIGHT} y2={SP_BOTTOM} stroke="rgba(255,255,255,0.25)" strokeWidth="2" />
                  <line x1={SP_LEFT} y1={SP_TOP}    x2={SP_LEFT}  y2={SP_BOTTOM} stroke="rgba(255,255,255,0.25)" strokeWidth="2" />

                  {/* X-axis ticks & grid — density */}
                  {densityTicks.map((v) => {
                    const px = SP_LEFT + (v / 100) * SP_W;
                    return (
                      <React.Fragment key={v}>
                        <line x1={px} y1={SP_BOTTOM} x2={px} y2={SP_TOP} stroke="rgba(255,255,255,0.06)" strokeWidth="1" />
