                      </React.Fragment>
                    );
                  })}

                  {/* Y-axis ticks & grid — rating */}
                  {ratingTicks.map((v) => {
                    const py = SP_BOTTOM - (v / 5) * SP_H;
                    return (
                      <React.Fragment key={v}>
                        <line x1={SP_LEFT} y1={py} x2={SP_RIGHT} y2={py} stroke="rgba(255,255,255,0.06)" strokeWidth="1" />
                        <text x={SP_LEFT - 10} y={py + 6} textAnchor="end" fontSize="18" fill={COLORS.muted}>{v}</text>
                      </React.Fragment>
                    );
                  })}

                  {/* Axis labels */}
                  <text x={(SP_LEFT + SP_RIGHT) / 2} y={SP_BOTTOM + 50} textAnchor="middle" fontSize="20" fill={COLORS.muted}>
                    Gym Density →
                  </text>
                  <text
                    x={SP_LEFT - 42}
                    y={(SP_TOP + SP_BOTTOM) / 2}
                    textAnchor="middle"
                    fontSize="20"
                    fill={COLORS.muted}
                    transform={`rotate(-90, ${SP_LEFT - 42}, ${(SP_TOP + SP_BOTTOM) / 2})`}
                  >
                    Rating →
                  </text>

                  {/* Opportunity zone quadrant (low density ≤ 30, low rating ≤ 3.2) */}
                  <rect
                    x={SP_LEFT}
                    y={SP_BOTTOM - (3.2 / 5) * SP_H}
                    width={(30 / 100) * SP_W}
                    height={(3.2 / 5) * SP_H}
                    fill="rgba(34,197,94,0.08)"
                    stroke="rgba(34,197,94,0.4)"
                    strokeWidth="2"
                    strokeDasharray="8,4"
                    rx="8"
                    opacity={scatterProg}
                  />
                  <text
                    x={SP_LEFT + (15 / 100) * SP_W}
                    y={SP_BOTTOM - (1.2 / 5) * SP_H}
                    textAnchor="middle"
                    fontSize="20"
                    fill={COLORS.green}
                    fontWeight="bold"
                    opacity={scatterProg}
                  >
                    OPPORTUNITY
                  </text>

                  {/* Data points — each is a circle with equal r so they stay circular */}
                  {DISTRICT_DATA.map((d) => {
                    const cx = SP_LEFT + (d.density / 100) * SP_W;
                    const cy = SP_BOTTOM - (d.rating / 5) * SP_H;
                    return (
                      <circle
                        key={d.name}
                        cx={cx}
                        cy={cy}
                        r={14}
                        fill={d.color}
                        opacity={scatterProg * 0.9}
                      />
