                  })}

                  {/* District labels next to dots */}
                  {DISTRICT_DATA.map((d) => {
                    const cx = SP_LEFT + (d.density / 100) * SP_W;
                    const cy = SP_BOTTOM - (d.rating / 5) * SP_H;
                    return (
                      <text
                        key={d.name + "-lbl"}
                        x={cx + 18}
                        y={cy + 6}
                        fontSize="17"
                        fill={d.color}
                        opacity={scatterProg * 0.8}
                      >
                        {d.name}
                      </text>
                    );
                  })}
                </svg>
              </div>
            </div>

            {/* Opportunity Zones map — 1180px wide, 500px tall */}
            <div
              style={{
                width: 1180,
                height: 500,
                backgroundColor: "rgba(255,255,255,0.03)",
                border: "2px solid rgba(255,255,255,0.08)",
                borderRadius: 24,
                padding: "20px 24px 16px",
                boxSizing: "border-box",
                opacity: mapProg,
                transform: `translateX(${interpolate(mapProg, [0, 1], [40, 0])}px)`,
