              }}
            >
              <div style={{ fontSize: 28, fontWeight: 700, color: COLORS.white, marginBottom: 12 }}>
                Opportunity Zones — Berlin
              </div>
              <div style={{ width: "100%", display: "flex", justifyContent: "center" }}>
                <svg
                  width={OPP_W}
                  height={OPP_H}
                  viewBox={`0 0 ${OPP_W} ${OPP_H}`}
                  style={{ display: "block", maxWidth: "100%", height: "auto" }}
                >
                  <rect width={OPP_W} height={OPP_H} fill="rgba(15,27,45,0.6)" rx="10" />

                  {/* Grid */}
                  {oppGridX.map((v) => (
                    <line key={v} x1={v} y1="0" x2={v} y2={OPP_H} stroke="rgba(255,255,255,0.05)" strokeWidth="1" />
                  ))}
                  {oppGridY.map((v) => (
                    <line key={v} x1="0" y1={v} x2={OPP_W} y2={v} stroke="rgba(255,255,255,0.05)" strokeWidth="1" />
                  ))}

                  {/* Opportunity zones — green pulsing rings */}
                  {oppZonePx.map(([cx, cy], i) => (
                    <React.Fragment key={i}>
                      <circle cx={cx} cy={cy} r={28 * pulseSize} fill="rgba(34,197,94,0.08)" opacity={mapProg} />
                      <circle cx={cx} cy={cy} r={16} fill="rgba(34,197,94,0.2)" stroke={COLORS.green} strokeWidth="2" opacity={mapProg} />
                    </React.Fragment>
                  ))}

                  {/* Saturated zones — red dots */}
                  {satZonePx.map(([cx, cy], i) => (
                    <circle key={i} cx={cx} cy={cy} r={12} fill={COLORS.red} opacity={0.6 * mapProg} />
                  ))}

                  {/* Best-location pin — at first opportunity zone */}
                  <g
                    transform={`translate(${oppZonePx[0][0]}, ${oppZonePx[0][1]}) scale(${pinScale})`}
                    style={{ transformOrigin: `${oppZonePx[0][0]}px ${oppZonePx[0][1]}px` }}
                  >
                    <circle cx={0} cy={-22} r={18} fill={COLORS.teal} />
                    <polygon points="0,0 -10,-18 10,-18" fill={COLORS.teal} />
                    <text x={0} y={-15} textAnchor="middle" fontSize="16" fill="white" fontWeight="bold">★</text>
                  </g>

                  {/* Legend */}
                  <g transform="translate(500, 20)">
                    <circle cx={10} cy={10} r={8} fill={COLORS.green} opacity={0.8} />
                    <text x={26} y={15} fontSize="18" fill={COLORS.muted}>Opportunity</text>
                    <circle cx={10} cy={38} r={8} fill={COLORS.red} opacity={0.7} />
                    <text x={26} y={43} fontSize="18" fill={COLORS.muted}>Saturated</text>
                  </g>
                </svg>
              </div>
            </div>
          </div>

          {/* ── ROW 3: Insight banner — 2400px wide ── */}
          <div
            style={{
              width: 2400,
              opacity: pinProg,
              transform: `translateY(${interpolate(pinProg, [0, 1], [30, 0])}px)`,
              backgroundColor: COLORS.tealDim,
              border: `2px solid ${COLORS.teal}`,
              borderRadius: 20,
              padding: "26px 60px",
              fontSize: 38,
              fontWeight: 700,
              color: COLORS.white,
              textAlign: "center",
              boxSizing: "border-box",
            }}
          >
            🎯 Best opportunity:{" "}
            <span style={{ color: COLORS.teal }}>Neukölln & Spandau</span> — Low competition, high demand
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── SCENE 6 ──────────────────────────────────────────────────────────────────

