                    <div style={{ fontSize: 22, fontWeight: 700, color: i === activeMonth ? COLORS.teal : COLORS.muted }}>{month}</div>
                    {i <= activeMonth && <div style={{ fontSize: 17, color: COLORS.green, marginTop: 5 }}>✓</div>}
